int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long r1, r2; scanf("%lld %lld", &r1, &r2);
    a[0] = r1; a[n - 1] = r2;
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%lld", a[i]);
    }
    printf("\n");
    return 0;
}

