#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long val; scanf("%lld", &val);
    int first = 1;
    for (int i = 0; i < n; i++) {
        if (a[i] != val) {
            if (!first) putchar(' ');
            printf("%lld", a[i]); first = 0;
        }
    }
    printf("\n");
    return 0;
}
